      "claim": "Modafinil has oral bioavailability of at least 40-65% in humans, supporting high F for a lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Metolazone is available in an approximately 100% bioavailable oral form, demonstrating that high F is achievable for a lipophilic, poorly soluble drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pirprofen shows a high and uniform degree of oral bioavailability in volunteers, supporting high F for a carboxylic acid-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Omapatrilat has absolute oral bioavailability of 21.9% in control subjects, which is just above the 20% threshold and supports a high prediction at this cutoff.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "CAB exhibits near-complete oral bioavailability in humans, supporting high F for a lipophilic, aromatic drug.",
      "evidence_role": "supportive"
    }
  ],
